import buy1Get1 from "../assest/offers/buy1-get-1.png";
import buy1Get2 from "../assest/offers/buy1-get-2.png";
import buy1Get3 from "../assest/offers/buy1-get-3.png";
import buy2Get1 from "../assest/offers/buy2-get-1.png";

export const getOfferImage = (offerQty) => {
  if (!offerQty || !offerQty.includes("+")) {
    return null; 
  }

  const [buyQty, getQty] = offerQty.split("+").map((v) => v.trim());

  if (buyQty === "1" && getQty === "1") return buy1Get1;
  if (buyQty === "1" && getQty === "2") return buy1Get2;
  if (buyQty === "1" && getQty === "3") return buy1Get3;
  if (buyQty === "2" && getQty === "1") return buy2Get1;

  return null;
};
